WordHunterWoW_QuestDataByFlavor = WordHunterWoW_QuestDataByFlavor or {}
WordHunterWoW_QuestDataByFlavor.forever = WordHunterWoW_QuestDataByFlavor.forever or {}
WordHunterWoW_QuestDataByFlavor.forever.enUS = WordHunterWoW_QuestDataByFlavor.forever.enUS or {}
local quests = WordHunterWoW_QuestDataByFlavor.forever.enUS
quests[6] = { title = "Bounty on Garrick Padfoot", description = "Garrick Padfoot - a cutthroat who's plagued our farmers and merchants for weeks - was seen at a shack near the vineyards, which lies east of the Abbey and across the bridge.  Bring me the villain's head, and earn his bounty!\n\nBut be wary, $n.  Garrick has gathered a gang of thugs around him.  He will not be an easy man to reach.", objectives = "Kill Garrick Padfoot and bring his head to Deputy Willem at Northshire Abbey.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "b7a60cc3579d12a3c0a2c9c1a4928d17d54fa4b5eb1d5d4fd9f7ea83e100ec74" }
quests[7] = { title = "Kobold Camp Cleanup", description = "Your first task is one of cleansing, $n.  A clan of kobolds have infested the woods to the north.  Go there and fight the kobold vermin you find.  Reduce their numbers so that we may one day drive them from Northshire.", objectives = "Kill 10 Kobold Vermin, then return to Marshal McBride.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "7ce9c420c694a42d13d5cac1083beb6469d3d2a04df04459f87d8f7900379a12" }
quests[13] = { title = "The People's Militia", description = "A band of vicious Defias Pillagers has been seen plundering the Gold Coast Quarry, Moonbrook and the Alexston Farmstead.  The People's Militia will not stand for such behavior.  Dispatch immediately, $n, and make the Light's presence known in Westfall.\n\nThe Gold Coast Quarry is near the shore, to the West of the tower.  As the next step of your training, I want you to kill 15 of those foul Defias Pillagers and 15 Defias Looters.", objectives = "Gryan Stoutmantle wants you to kill 15 Defias Pillagers and 15 Defias Looters and return to him on Sentinel Hill.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "f844f260b6fd4f02b13747be2ed345fd22a98549e114fac32674e322fd2e7bc3" }
quests[15] = { title = "Investigate Echo Ridge", description = "$n, my scouts tell me that the kobold infestation is larger than we had thought.  A group of kobold workers has camped near the Echo Ridge Mine to the north.\n\nGo to the mine and remove them.  We know there are at least 10.  Kill them, see if there are more, then report back to me.", objectives = "Kill 10 Kobold Workers, then report back to Marshal McBride.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "0f95144d569ceb695286b57c1af8e3206a2e9a850f518d15e51e707089c007c7" }
quests[18] = { title = "Brotherhood of Thieves", description = "Recently, a new group of thieves has been hanging around Northshire.  They call themselves the Defias Brotherhood, and have been seen across the river to the east.\n\nI don't know what they're up to, but I'm sure it's not good!  Bring me the bandanas they wear, and I'll reward you with a weapon.", objectives = "Bring 12 Red Burlap Bandanas to Deputy Willem outside the Northshire Abbey.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "5e2f22dbad144e2787f602f7c8f159b212f0f10bb66b606f38a491185bb0c427" }
quests[21] = { title = "Skirmish at Echo Ridge", description = "Your previous investigations are proof that the Echo Ridge Mine needs purging.  Return to the mine and help clear it of kobolds.\n\nWaste no time, $n.  The longer the kobolds are left unmolested in the mine, the deeper a foothold they gain in Northshire.", objectives = "Kill 12 Kobold Laborers, then return to Marshal McBride at Northshire Abbey.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "f2989c20bff76c9bfdd74a1da1fdc33bf090946ae737bd99c8648dba209fe6ac" }
quests[33] = { title = "Wolves Across the Border", description = "I hate those nasty timber wolves!  But I sure like eating wolf steaks...  Bring me tough wolf meat and I will exchange it for something you'll find useful.\n\nTough wolf meat is gathered from hunting the timber wolves and young wolves wandering the Northshire countryside.", objectives = "Bring 8 pieces of Tough Wolf Meat to Eagan Peltskinner outside Northshire Abbey.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "ea7829fdf914771b4c120ecacdc0f37e6effa21981a4a55e5ea0464ca7808635" }
quests[54] = { title = "Report to Goldshire", description = "$n, you are a $c with proven interest in the security of Northshire.  You are now tasked with the protection of the surrounding Elwynn Forest.\n\nIf you accept this duty, then I have prepared papers that must be delivered to Marshal Dughan in Goldshire.  Goldshire lies along the southern road, past the border gates.", objectives = "Take Marshal McBride's Documents to Marshal Dughan in Goldshire.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "5c353d279c55ed64f7bba18a81950fe20a49fb9b6093fae9b51797a6fc9dff7d" }
quests[92] = { title = "Redridge Goulash", description = "Nothing would please me more than to make you some Redridge Goulash. But there's a slight problem. During the recent orc uprising I fed the entire brigade of Stormwind troops. My cupboard is now bare. But if you can provide me with the ingredients, I'd be happy to oblige.\n\nJust bring me five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.", objectives = "Chef Breanna of Lakeshire wants five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "170a89bbaa2b4983446d761dfe03f7485bdf7288c501846a0b7418b6a9b7ab10" }
quests[116] = { title = "Dry Times", description = "I find myself in quite a pinch here, $n.  The bottles are close to running dry.  The latest booze shipment is long overdue.  The orc invasion has been hell.\n\nPerhaps you can go to work for me?\n\nI need you to pick up a keg of Thunderbrew Lager from Grimbooze Thunderbrew in the Westfall hills, a cask of Merlot from Stormwind, a bottle of Moonshine from Darkshire and a skin of Sweet Rum from Goldshire.  Bring those back to me and I will see to it you are rewarded.", objectives = "Barkeep Daniels of Lakeshire needs a keg of Thunderbrew Lager, a cask of Merlot, a bottle of Moonshine and a skin of Sweet Rum.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "38667ddb687d956ca625e94527bd072aac51f0da30f20371909974cb00736988" }
quests[118] = { title = "The Price of Shoes", description = "I've been using so much iron keeping the Stormwind Guards outfitted, I don't have enough to supply the stable's horses with shoes!\n\nTake this note to Blacksmith Argus in Goldshire.  It explains to him my problem and requests a shipment of horseshoes.", objectives = "Take Verner's Note to Smith Argus in Goldshire.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "d9570e28c41c7f1d698f21489dc41f19843615a60640842cb9bd4fc38f3dd49d" }
quests[121] = { title = "Messenger to Stormwind", description = "While I wait for a response from the King I want you to carry this letter to Magistrate Solomon. \n\nDismissed, $c!", objectives = "Take General Marcus Jonathan's letter of response to Magistrate Solomon in Lakeshire.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "7a64ba6768670a80f012fddde0162e111d0e9cb6f52342b2be381a6b69627d33" }
quests[125] = { title = "The Lost Tools", description = "I could really use a hand here, $n.  With the town under siege, it's been hard to get supplies.  My tools were being delivered from Goldshire by wagon but the bridge was blown out.  We put the tools in a boat but the orcs hit it with a catapult.  Just my luck, my toolbox sank right to the bottom of the lake.\n\nRetrieve my toolbox, $n, and I'll make it worth your while.", objectives = "Foreman Oslow of Lakeshire wants you to retrieve his toolbox from the bottom of Lake Everstill.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "63306728f093734cfe2278ae748d6c7d0616b1658aef104977c92e3a755137db" }
quests[141] = { title = "The Defias Brotherhood", description = "The Stonemasons' Guild was run by a man named Edwin VanCleef.  VanCleef was responsible for rebuilding Stormwind after the orcs razed it in the First War.  Apparently, VanCleef and his men were unhappy with their treatment by the King after the reconstruction was complete.  That just might explain a thing or two.\n\nI have written a more detailed account for your Master in Westfall.  Take this to him at once!", objectives = "Take Shaw's report to Gryan Stoutmantle in Westfall.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "7521329ac32cd0bfeac73ace57a82976846313567349b7f4e1edec6abeeb57b6" }
quests[169] = { title = "WANTED: Gath'Ilzogg", description = "Wanted! Gath'Ilzogg, Leader of the Blackrock attacks on Stonewatch Keep and raids against the township of Lakeshire. \n\nGath'Ilzogg is extremely dangerous.  He is reportedly holed up in the recently conquered keep plotting the Blackrock clan's further crimes against humanity.  The orc infestation must be quelled at all costs.  A gracious reward will be given to whatever brave soul can deliver the head of Gath'Ilzogg to Magistrate Solomon.", objectives = "Kill Gath'Ilzogg and bring his head to Magistrate Solomon in Lakeshire for the reward.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "0ceb65602c7b1972d7d53d4ab2283f7c464d35c11df17de414d620ec467ddba6" }
quests[170] = { title = "A New Threat", description = "I hope you're here to lend us a hand, $c. After the last trogg attack, we could use all the help we can get.\n\nI hear the buggers have been popping up all across the lands, and it seems Coldridge Valley is no exception. They've been spotted all over the hills to the southeast and near the frozen lake.\n\nAnd that's not all, just a few nights ago, they attacked and overran our camp to the west! \n\nWe're a bit shorthanded here, $g lad : lass;, and we need strong arms to help drive the troggs back.", objectives = "Balir Frosthammer wants you to kill 6 Rockjaw Troggs and 6 Burly Rockjaw Troggs.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "fab293ec168020fbd17979f84a02398f7e7e6206bdb7a32fefc9c5bbaf48232a" }
quests[179] = { title = "Dwarven Outfitters", description = "What do we have here? You look as though you might need something to keep your hands warm, hm?\n\nI'll tell you what would help: a pair of nice, warm gloves. And, being the kind soul that I am, I'd be more than happy to provide you with a suitable pair. I've one condition, however.\n\nI need you to go get me some wolf meat. Nice arrangement, hm? You bring me some wolf meat, and I'll make sure you don't lose any digits to frostbite. Well, what do you say?", objectives = "Sten Stoutarm would like 8 pieces of Tough Wolf Meat.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "313b869ad595bdd677131bbd664077ca10321516858ab8f17cf1e56a9c8302c6" }
quests[180] = { title = "WANTED: Lieutenant Fangore", description = "Wanted: Lieutenant Fangore\n\nKnown leader of the Shadowhide Gnoll Clan, working under the enemy of the Township and Kingdom, Morganth.  By mandate of Magistrate Solomon, this vile betrayer of Stormwind is wanted dead.  Show his paw to the Magistrate as proof of his death.", objectives = "Kill Lieutenant Fangore and return to Magistrate Solomon in Lakeshire with his paw.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "7f2d396c0ac8a7de1daf96ffdace269725da5c6480fd9a639704a788276e0c99" }
quests[182] = { title = "The Troll Cave", description = "My brother Senir and I were sent to different parts of Dun Morogh to investigate the threat posed by the trolls. The Senate has its hands full with the troggs, so they've no need for further annoyances.\n\nFrom what I've seen, the trolls aren't well situated here in Coldridge Valley--mostly the southern cave. I'd say that the army will not be necessary. A few strong arms should be more than enough.\n\nPerhaps you'd like to assist in this endeavor? I have the authority to offer compensation for your help.", objectives = "Grelin Whitebeard would like you to kill 14 Frostmane Troll Whelps.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "7a94d81c550939d312814c1b8c8024d5824e87df5733f317ef9ca63b6b1f1d00" }
quests[183] = { title = "The Boar Hunter", description = "Nothing like a day of boar hunting, eh?\n\nThough, here in Coldridge Valley, there are so many boars it almost takes the fun out of it. No need to get them charging. They're all angry and ready without any help. In fact, recently, there've been so many boars in the area, it's become dangerous for me to do my daily hunting.\n\nLong story short, if you could help me kill some of the boars, I would appreciate it.", objectives = "Talin Keeneye would like you to kill 12 Small Crag Boars.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "e49701e9537437706d2d475519545c3eb1ccf1c096e0b25f974f5f93c6f9364b" }
quests[218] = { title = "The Stolen Journal", description = "My journal! They took it away to the cave. The one that had it... It was a big brute with some odd markings on his skin and face. I didn't get a much better look than that.\n\nYou've had some luck with the trolls, maybe you could go get it back for me?", objectives = "Grelin Whitebeard wants you to kill Grik'nir the Cold, and retrieve his journal.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "cfb4b92dbd6eec620d4351771a4a46d0848c07b89cc183f90e9cbf26215438f2" }
quests[233] = { title = "Coldridge Valley Mail Delivery", description = "Hm, I don't suppose you'd be willing to do a favor for me, $g lad : lass;? A stack of letters came through the pass today, but I don't have the time to send them along.\n\nThey're all addressed to Talin Keeneye. You can find him to the west down the road. He's set up camp next to the frozen lake.\n\nWhat do you say?", objectives = "Deliver the stack of letters to Talin Keeneye.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "f27c6f5c553da739745c00e8fcd3855b968b1dc9c7f569248e137ae4208f9ee6" }
quests[234] = { title = "Coldridge Valley Mail Delivery", description = "If I remember correctly, Grelin's camp is down the road to the southeast. No doubt he'll be eager to get his mail.", objectives = "Deliver the letter to Grelin Whitebeard.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "c335e02c1a565c3c7b088b7ca1dc083fec9031d1f193a769b979ba6643da923c" }
quests[246] = { title = "Assessing the Threat", description = "We don't have men to spare, but something must be done about those gnolls you reported to me.\n\nScout southern Redridge for gnolls.  Harry them, kill those you can and report back to me with a count of their numbers and an assessment of the threat they present.  You may find those gnolls camped all along the southern road of Redridge.\n\nDo this for the Stormwind Army, $n, and you will be rewarded.", objectives = "Kill 10 Redridge Mongrels and 6 Redridge Poachers, then report back to Deputy Feldon in Lakeshire.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "17ba6f88104ddf1ad9aaae6f34d46020e33a7c447ab28572fb53d6021df9a615" }
quests[282] = { title = "Senir's Observations", description = "I was planning on sending my apprentice to my brother Senir with my report, but I would feel much better were it placed in more... reliable hands. That is, of course, if you wouldn't mind?\n\nHmm... you'll have to take the tunnel to get to Kharanos.\n\nSpeak with Mountaineer Thalos before going through the tunnel. It's completely infested with troggs now.\n\nFollow the road back to Anvilmar, then keep heading east to the tunnel, Thalos is stationed nearby.", objectives = "Speak with Mountaineer Thalos.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "ffc2727c7f9d169a3cd552a63cc18669d4a189556f64f89934f2ce8b6f4bdb1c" }
quests[287] = { title = "Frostmane Hold", description = "I'm behind on my report, and could use your help, $n. I just managed to find where the trolls are holed up, but I saw so many trolls, I was afraid to go in.\n\nHere's what I need... Go down to the cave, poke around inside, kill a few of the trolls, then come back here.\n\nTake the road north out of Kharanos, when you get to the bridge, follow the frozen river west until you reach Iceflow Lake. You'll find Brewnall Village on the west bank. The Hold is southwest of the village.", objectives = "Explore Frostmane Hold, and kill 5 Frostmane Headhunters for Senir Whitebeard in Kharanos.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "516065ae4c25541d0498332a8304c212b816784d34ce8f8f20fce818015d87aa" }
quests[313] = { title = "The Grizzled Den", description = "Driving a Siege Engine isn't for everyone.  It takes an iron grip and nerves of steel...lucky I have both!  How about you?  How's your mettle?  Want to prove it to me?\n\nWell...I'm looking to make my engine, Trollplow, a little more cozy.  How about you get me a heap of Wendigo Manes from the Grizzled Den, west of Kharanos.  Those manes would make a great rug for Trollplow's inside deck!", objectives = "Gather 8 Wendigo Manes and bring them to Pilot Stonegear.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "371d45798f3144b2cacaa30f4fc21e3135267ae07f92a97b9370d280d463c9a5" }
quests[314] = { title = "Protecting the Herd", description = "We heard the cries in the middle of the night.  Then this morning, sure enough, the herd was missing two rams.  That dastardly beast known as Vagash has been preying on our livelihood.  With most of King Magni's army off in distant lands fighting with the Alliance, there is no one to keep Vagash at bay.\n\nPerhaps you are brave enough to seek out the beast and slay him.  Bring me one of his fangs and I will reward you.  Vagash lurks just above the ranch here, but be warned, he is deadly.", objectives = "Rudra Amberstill wants you to slay Vagash and bring his fang to her at the Ram ranch.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "cd09e3ed6fb6a15060530dc520b5bd149624123e679d482bb6750d68947c7d75" }
quests[317] = { title = "Stocking Jetsteam", description = "I'm preparing to start a mission for the Siege Brigade.  It's a long one, and I need to stock Jetsteam with a month's worth of supplies.  So while Steelgrill is working on my tank, can you do some hunting for me?\n\nI'll need some fur for bedding, and boar meat for food.  You can get meat from boars and fur from the bears... you can find them both in the snow fields south of the Grizzled Den.", objectives = "Gather 4 Chunks of Boar Meat and 2 Thick Bear Furs, and deliver them to Pilot Bellowfiz at Steelgrill's Depot.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "81d4c4a34f40ad7c9ce3b5688e6fbc510f2e6b04e69b3f5d6dfed1dc69ab837c" }
quests[353] = { title = "Stormpike's Delivery", description = "The Stormpikes are a respected dwarven clan, and are well known for their fine and discerning tastes.  So it's no wonder that Gringer Stormpike, a Mountaineer of Ironforge, commissioned me to craft him a weapon.\n\nThe weapon is finished, but... Mountaineer Stormpike is far away, in distant Loch Modan.  If you plan on traveling to the north, can you deliver this package to him?\n\nMy last message from Mountaineer Stormpike said he's stationed at the northern guard tower in Loch Modan.", objectives = "Deliver the Package for Stormpike to Mountaineer Stormpike in Loch Modan.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "00f398150bee31b63fea7f17e0e0e4e3bd6bbc39178ab76b6bd9d7b36f8261de" }
quests[384] = { title = "Beer Basted Boar Ribs", description = "Nothing my tavern patrons enjoy more than some Beer Basted Boar Ribs!  Only problem is, the local trapper who used to bring me supplies enlisted in the King's Army to help with the war on the Alliance front. \n\nMaybe you can help me out?  If you bring me six crag boar ribs and a Rhapsody Malt from the tavern here, I'll give you the family recipe for my famous Beer Basted Boar Ribs, not to mention a free sample!  The secret's in the Malt!", objectives = "Ragnar Thunderbrew in Kharanos wants 6 Crag Boar Ribs and a mug of Rhapsody Malt.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "73e5e9a702ab51de2490429c0db9859e57c6b95e0eee6fe839a3db19b74394c2" }
quests[400] = { title = "Tools for Steelgrill", description = "Beldin Steelgrill owns the local mechanic shop, and he's the best siege engine tech there is!  But he's not forgiving to his tools.  I swear he almost breaks more arclight spanners than we can supply him with!\n\nWe just filled his last order for tools.  If you deliver it to him I'm sure he'll make it worth the effort.\n\nHis shop, Steelgrill's Depot, is just northeast of Kharanos.  And it's a local haunt for veteran siege engine pilots, so keep your ears open for opportunities while you're there.", objectives = "Deliver Steelgrill's Tools to Beldin Steelgrill.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "8887c726b68a3c2f63f509d6e96f97aeb0b5d6c4ab9696f44a170df98ee61189" }
quests[420] = { title = "Senir's Observations", description = "The troggs in the tunnel are extremely hostile, and haven't shown any hesitation in attacking travelers through the tunnel. You seem tough enough, though, so you should probably be safe.\n\nDirections? If you're going to speak with Senir, you'll find him in Kharanos.\n\nMake your way through the tunnel, and after you come out on the other side, just keep following the road, it'll run right into Kharanos.", objectives = "Deliver Grelin's report to Senir Whitebeard in Kharanos.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "e89dc158019af4596f87fe23e79ab7db0177d331c1123c76430eefca5909643b" }
quests[456] = { title = "The Balance of Nature", description = "Greetings, $n.  I am Conservator Ilthalaine.  My purpose in Shadowglen is to ensure that the balance of nature is maintained.\n\nThe spring rains were particularly heavy this year, causing some of the forest's beasts to flourish while others suffered.\n\nUnfortunately, the nightsaber and thistle boar populations grew too large.  Shadowglen can only produce so much food for the beasts.  Journey forth, young $c, and thin the boar and saber populations so that nature's harmony will be preserved.", objectives = "Kill 7 Young Nightsabers and 4 Young Thistle Boars and return to Conservator Ilthalaine.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "8dc958eaaabdeb7c56dae23673107651cc503e2474064f65b87c0b5df443dce8" }
quests[457] = { title = "The Balance of Nature", description = "Thinning the younger population of creatures here in Shadowglen was a good start, $n, but there is still work to be done.\n\nThe resources of the forest will be depleted too quickly if the problem is not addressed.  Killing nature's beasts is a necessary evil for the good of all who share the land.  Venture into the forest and slay mangy nightsabers and thistle boars in the name of balance.", objectives = "Conservator Ilthalaine needs you to kill 7 Mangy Nightsabers and 7 Thistle Boars.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "47a01df0933fa5d1e63d297aad5cc390d5541221e771d65c01f2c67fbd3e18a2" }
quests[458] = { title = "The Woodland Protector", description = "Thank goodness you are here, $c. Strange news has traveled to me through the whisperings of the forest spirits.\n\nThe mysterious woodland protector, Tarindrella, has returned to Shadowglen. The dryad's presence has not been felt in the forests of Kalimdor in years. Something is surely amiss if she has journeyed back to this land.\n\nSeek out Tarindrella and see what business she tends to in our grove. One of the Sentinels reported seeing her to the southwest of Aldrassil.", objectives = "Seek out the dryad known as Tarindrella.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "7b505b5168281fd540fb133aa911a13536af42062661996c33e80656c306f68b" }
quests[459] = { title = "The Woodland Protector", description = "Something evil is brewing in the forests of Teldrassil.  Look long the hills to where the peaceful furbolgs used to dwell.  They have deserted their homes and are amassing under the name of the Gnarlpine tribe.\n\nOnly the corruption of wicked Fel Moss could cause such a transformation.  The grells and grellkin have infested the area and are threatening the residents of Shadowglen.  \n\nEngage these grells and grellkin, $n, and see if they are indeed caught under the enchantment of the wicked Fel Moss.", objectives = "Collect 8 Fel Moss and bring them to Tarindrella.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "c11fb815bd2625a3f8e0d2390ac4b860f3c939846b6790a9b3ce8dc90491549d" }
quests[744] = { title = "Preparation for Ceremony", description = "$n, my brother soon stands before Chief Bloodhoof, and it is my honor to make his headdress for him.\n\nI want to ask a favor of you while I finish tanning these leather straps. There is not time for me to find enough feathers, and I was wondering, would you gather more for me?\n\nYou can find feathers of the correct size from the harpies residing far to the north and northwest of Thunder Bluff. I need only 6 azure and 6 bronze feathers to complete the design.", objectives = "Collect 6 Azure Feathers and 6 Bronze Feathers, and bring them to Eyahn Eagletalon in Thunder Bluff.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "dcef6350685d1f2e4885210727255e11b9e63896887c5985356d138ac9d9a5c3" }
quests[783] = { title = "A Threat Within", description = "I hope you strapped your belt on tight, young $c, because there is work to do here in Northshire.\n\nAnd I don't mean farming.\n\nThe Stormwind guards are hard pressed to keep the peace here, with so many of us in distant lands and so many threats pressing close.  And so we're enlisting the aid of anyone willing to defend their home.  And their alliance.\n\nIf you're here to answer the call, then speak with my superior, Marshal McBride.  He's inside the abbey behind me.", objectives = "Speak with Marshal McBride.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "ad7c2ba0204ca4745d479910e8e8a01e1d3c9968499756b66c1d694c3ca23693" }
quests[806] = { title = "Dark Storms", description = "We cannot allow the Burning Blade a foothold in Durotar!  We must destroy them before their evil festers!\n\nI have undergone my own investigations and found that a Burning Blade warlock, the goblin Fizzle Darkstorm, has camped within Thunder Ridge to the northwest.  There he and his cultist minions spread chaos.\n\nFind and defeat Fizzle, and bring me his dead claw!", objectives = "Bring Fizzle's Claw to Orgnil Soulscar in Razor Hill.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "24095f160d9664b4630d95439d78b88d7c1216164db75035bef3776d23ac5c6e" }
quests[809] = { title = "Ak'Zeloth", description = "Since the last great war when the Burning Legion was defeated, I have searched for sources of demonic corruption in orc society.  The collar you brought me confirms my fears.\n\nIt belongs to the Burning Blade, a cult that rallies around an item of demonic power.  It is called the Demon Seed, and it resides in the Barrens atop Dreadmist Peak.  It must be destroyed!\n\nGo to Far Watch Post, on the border of the Barrens to the west, and speak with my assistant, Ak'Zeloth.  He will direct you further.", objectives = "Speak with Ak'Zeloth in the Barrens.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "57dcb96632ee2613266c38aee63aedb1c787f38525623d84e3cb1ea145932ef9" }
quests[812] = { title = "Need for a Cure", description = "$n... your timing is perfect. I just hope I can compliment your haste as well.\n\nI was careless while fighting a few of the venomtails nearby, and one of them stung me deeply. I can feel its poison weakening me even as we speak. At this rate, I got maybe an hour left to live. But I'll need your help if I'm to do so...\n\nKor'ghan in Orgrimmar knows how to make the antidote. Find him... and hurry, $n. I won't be able to last much longer. He should be in the Cleft of Shadow.", objectives = "Find Kor'ghan in Orgrimmar and get the Venomtail Antidote. Then bring the antidote to Rhinag near the northwestern border of Durotar.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "36b3a324c90499a63e27d7d5498bbf53666700780970c75cc7621581f5aaaf39" }
quests[832] = { title = "Burning Shadows", description = "<Words emanate from the pendant and into your mind.>\n\nGazz'uz?\n\nGazz'uz...report!\n\nThere is word of your discovery in Skull Rock.  You must prepare for an attack!\n\nGazz'uz, I order you to speak!  Speak or I will make sure Neeru Fireblade knows of your presence, and he will descend on you with swift brutality.\n\nDo not test your skills against Neeru...\n\n...Gazz'uz, are you there...?", objectives = "Take this eye to Neeru Fireblade.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "d3ca00917bbc1326c95adc20e1994dfddd0b52960af150cc26d23b773330986b" }
quests[844] = { title = "Plainstrider Menace", description = "Your first prey will be easy.\n\nThe plainstriders to the east have been harassing our food supplies and have become a nuisance.\n\nPut down the plainstriders and return to me with their beaks.", objectives = "Collect 7 Plainstrider Beaks and return them to Sergra Darkthorn in the Crossroads.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "02508ab75c081753e6d37a6cf104b702b46016daa5fd1661987e3f0a26d715c6" }
quests[848] = { title = "Fungal Spores", description = "The oases of the Barrens hide a mystery.  Life energy flows from their waters, invigorating the plants and beasts that drink it.\n\nInvigorating, and altering.\n\nThere is a mushroom that grows near these oases.  Its spores hold properties that we, the apothecaries of Lordaeron, find useful.\n\nBring me these spores and you will earn our gratitude.", objectives = "Bring 4 Fungal Spores to Apothecary Helbrim at the Crossroads.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "faf7466cf943b5ed7c19b8fe64515533be889b8b21021bf56191ce195c2fe02e" }
quests[866] = { title = "Root Samples", description = "The herbs of the Barrens are not quite like herbs in other lands.  Their properties are mostly the same, but the oasis water here alters the plants; they are just slightly different.\n\nI want to study those differences... to see if they're exploitable!\n\nIf you are skilled in herbalism, then gather root samples off the herbs you find in the Barrens.  Bring back these samples so that I may compare them with herbs from other regions.", objectives = "Bring 8 Root Samples to Mebok Mizzyrix in Ratchet.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "7c134efe08e5b7f20a54fcac74f3652c8b26d41bf817eb891019d32e4d5c6f91" }
quests[869] = { title = "Raptor Thieves", description = "Not long ago, a shipment of silver was stolen from our guard tower.  It was meant as payroll to the Crossroads' guards, and we want that silver back.\n\nThe strange thing is... we caught one of the thieves on the night of the theft.  And... it was a raptor!  Unbelievable!\n\nI don't know what raptors would want with silver.  But I don't care -- I want the raptors dead so they won't steal from us again!\n\nHunt raptors in the Barrens.  Collect for me their heads!", objectives = "Bring 12 Raptor Heads to Gazrog at the Crossroads.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "142b6a7aad184025cae5a7caff00a719251c08a193d82430508d64d63f5b22e7" }
quests[870] = { title = "The Forgotten Pools", description = "Long ago, the Barrens was a lush place, teeming with life.  But war and cataclysm raged across the land, scorching it and leaving a dry husk.  Such is the way of things, and it saddens my heart.\n\nBut within the past few years, new oases have formed in the Barrens, and life stirs.  And deep down, we druids sense a power leaking its way to the surface.\n\nWe must find its source.  Travel to the Forgotten Pools, northwest of the Crossroads.  Search its waters for a source of power, then return here.", objectives = "Report back to Tonga Runetotem with your findings.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "848b6d7c5ca6f10f8d17579313c24b55d088307a7b649479363029627e0b1d34" }
quests[871] = { title = "Disrupt the Attacks", description = "All the quilboars are our enemies, $n. Some just prove to be more of a nuisance than others.\n\nThe Razormane tribe has been attacking our supply lines from Durotar, causing us no end of annoyance. I have scouts seeking the leader of these raids, but until then, any losses you can inflict on the filthy pig men would aid us.\n\nStart in the northeast towards Durotar. You can always tell their dens from the huge thorny vines that come up from the earth. Seek them out, and slay them.", objectives = "Of the Razormane tribe, kill 8 Water Seekers, 8 Thornweavers and 3 Hunters, and then return to Thork in the Crossroads.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "53ea73ee031f9ab629e01804d990bfcf97c705fcf7d4789f8f8b57f6bf2c6614" }
quests[887] = { title = "Southsea Freebooters", description = "I sure wish Vice Admiral Grezzlik did a better job of keeping the seas safe for our trading vessels. With all the gold the trade princes have poured into the Trade Fleets, it ticks me off to see so many pirates running willy-nilly, raiding my ships and stealing my goods!\n\nI heard that the Southsea Freebooters have set up a camp just south of here. They've been a real thorn in my side and if Grezzlik won't take care of them, well, maybe you can help me get rid of them.", objectives = "Kill 12 Southsea Brigands and 6 Southsea Cannoneers for Gazlowe in Ratchet.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "8f8da9c1122934d7f29bbb578b379df586c24192dfa9c00855bb7f6b9d148c90" }
quests[894] = { title = "Samophlange", description = "The Venture Company set up a small research facility far to the north of here, southwest of the Sludge Fen. I don't know very much about what they're doing, but did manage to discover that they're experimenting with something called a \"samophlange\".\n\nNow what the heck is a samophlange? Well, whatever it is, I want to examine it, so I need someone to go get it.\n\nI obtained a copy of their control system operating manual, you should be able to figure out how to disengage the samophlange from it.", objectives = "Access the control console at the Venture Company research site.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "710d18dea904afd6e5f2f68c087d1ea0ffd05eb0f90a4bbb0ad71666c99ee154" }
quests[895] = { title = "WANTED: Baron Longshore", description = "WANTED!\n\nBaron Longshore, Captain of the Heedless\n\nCaptain Longshore of Gilneas leads vessels of the Southsea Freebooters, and is wanted on charges of piracy. Remains must be in identifiable condition!\n\n-- Gazlowe", objectives = "Bring the head of Baron Longshore to Gazlowe in Ratchet.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "9749a2bba0422c20aa147728f80e8a9580c89120d2e4c1984d8763a000cf8b91" }
quests[916] = { title = "Webwood Venom", description = "I came to Shadowglen to observe the webwood spiders that dwell in the Shadowthread Cave.  They are cousin to a much smaller variety of spider; I believe the world tree has had a profound effect on them, and I would like specimens to study to confirm this.\n\nFirst, I would like some of their venom.  Gather Webwood venom sacs from the spiders in and around the Shadowthread Cave, to the north.  I can then examine them for similarities with their smaller cousin's venom.", objectives = "Bring 10 Webwood Venom Sacs to Gilshalan Windwalker at Aldrassil.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "5cb2427528e07a73902a3b3f466961545424f2944935af7d7a9dab530d3b672d" }
quests[1524] = { title = "Call of Fire", description = "You are powerful enough to wield the totem of fire, but that does not mean you are ready.\n\nAlong the Southfury River in Durotar, before the Great Sea, lies a hidden trail to one of the highest peaks in the land. Find your way to the top and you shall find one of our holy shrines watched over by Telf Joolam--the Shrine of the Dormant Flame.\n\nTake this torch to him--it marks that you attempt to tame fire. Return it to me aflame by the brazier at the shrine and I will see you are given the totem of fire.", objectives = "Bring the Torch of the Dormant Flame to Telf Joolam in Durotar.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "0d5217de588b60f92e596b8caa21435704ac1aec985e9311297650edf91755ef" }
quests[1883] = { title = "Speak with Un'thuwa", description = "Un'thuwa, tribal mage of Sen'jin Village, detects a disturbance in the magic currents of Durotar and asks for aid.  Speak with Un'thuwa and do what you can to help him.\n\nDo this, and in time further secrets will be revealed to you.", objectives = "Speak with Un'thuwa.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "39c47307471e30227e26fae5c4102b6a6b76e834d06dcf1227465aebfd16bf22" }
quests[2039] = { title = "Find Bingles", description = "We've lost contact with Bingles! He was sent on a reconnaissance mission over Gnomeregan and hasn't reported back in over a week. I just know he's gone and blown himself up.\n\nHe was last seen flying over the Loch. Perhaps you can investigate, $n.", objectives = "Find Bingles Blastenheimer in Loch Modan.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "8475db6fddddba83fd26a3f424f7554f0aee0a0d582657cfea17578f4151d970" }
quests[2040] = { title = "Underground Assault", description = "Gnomeregan has fallen under the control of those dastardly troggs! The situation is grave but perhaps you can help, $n.\n\nDeep in the Deadmines is a functional goblin shredder. Find that shredder and bring back the intact power supply. With the shredder's power supply, we can give our gyrodrillmatic excavationators the power they need to break through the rocky underground borders of Gnomeregan, opening the way for a gnomish assault!", objectives = "Retrieve the Gnoam Sprecklesprocket from the Deadmines and return it to Shoni the Shilent in Stormwind.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "ba003991ffb23bce8e950f99d075a794dc1f8618697f8fa17d3776fad9125fdb" }
quests[2160] = { title = "Supplies to Tannok", description = "Hey! You look like a hearty adventurer. If you're planning on braving the pass, do you suppose you could bring a package to the inn in Kharanos?\n\nYou were planning on stopping at the inn, right? If you make it through the pass, you'll definitely want to take a breather there.\n\nAnyways, bring this to Tannok Frosthammer, the innkeeper's assistant. I can't get through the pass myself, and it'll be days until a Mountaineer escort comes through!", objectives = "Deliver the Crate of Inn Supplies to Tannok Frosthammer in Kharanos.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "3cc2f1c64b511c9af15f3165c188cb62dcf481df3a80a427a55f557530d57d18" }
quests[3102] = { title = "Encrypted Letter", description = "I was asked to bring this to your attention as soon as you returned from the kobold camps, $n. It appears to be a letter sealed with the insignia of Jorik, one of our local trainers. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", objectives = "Read the Encrypted Letter and speak to Jorik Kerridan in the stable behind Northshire Abbey.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "c66d85a26c506a08325818cb75654dbb77f334fd98ff82ff229921b98dec91af" }
quests[3118] = { title = "Encrypted Sigil", description = "This sigil was given to me by a messenger from our rogue trainer, Frahun. It seems Frahun would have words with you when you have a moment. Read it and bring it to him afterwards.", objectives = "Read the Encrypted Sigil and speak to Frahun Shadewhisper in Shadowglen.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "a7360c5fba9f7e841204f52d4328718d5985019f08d5446758325c347456e462" }
quests[3361] = { title = "A Refugee's Quandary", description = "We drove the troggs out of Gnomeregan, but then it all went so horribly wrong!  Now our home is completely irradiated, and we gnomes have been scattered all over Dun Morogh.\n\nIn my haste to get away from the radiation, I lost all my personal belongings and tools.  It was the trolls that got them.  They stole my chest, my box, and my bucket of bolts!  They took them back to their camps southwest of Anvilmar.\n\nI'm no adventurer - could you find my things and bring them here to me, please?", objectives = "Bring Felix's Box, Felix's Chest and Felix's Bucket of Bolts to Felix Whindlebolt in Anvilmar.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "e5bdaa1457cea606337b58b875a35924ec235024209c7344d4e7ff69fa26aff7" }
quests[3364] = { title = "Scalding Mornbrew Delivery", description = "Gah!  I was supposed to get this delicious scalding mornbrew to Durnan Furcutter inside Anvilmar a while ago now, but I had to deliver one to Grelin here first.  I'll never make it to Anvilmar before the brew runs cold!\n\nYou look fast.  Maybe you can make it.  This cup will only stay hot for five more minutes, and Durnan didn't order \"chilly\" mornbrew, so get going.  Anvilmar is to the northeast, a settlement dug into the mountain.\n\nThanks, $n, and don't forget to bring me back my mug!", objectives = "Take a Scalding Mornbrew to Durnan Furcutter inside Anvilmar before it gets cold in five minutes!", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "d9537155e7c663bd749ec0e064e8af98d97cf86818fe267b3188b8bfb447d634" }
quests[3365] = { title = "Bring Back the Mug", description = "Now that hit the spot!  Nothing like a piping hot - nay, SCALDING mornbrew on a cold winter's day to warm your cackles of yer soul.\n\nHere ya go $n - be a pal and take this empty mug back to Nori for me, would ya now.", objectives = "Return Nori's Mug to Nori Pridedrift.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "2d7c056e77185b5021c078918717b33dd85db7e954c1e960f2349b7fb99e6158" }
quests[3519] = { title = "A Friend in Need", description = "Ughhh... I was bitten very badly by a spider named Githyiss the Vile while exploring the spider cave very close to here. I am sure I have been seriously poisoned; you must help me.\n\nPlease tell Dirania Silvershine. She will be able to help me.\n\nHurry... I'm so dizzy...", objectives = "Speak to Dirania Silvershine in Shadowglen.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "3f8b9b1277fb77ba9ef7610e4b57f9befcd733fef5954b2c0e43e853d1966982" }
quests[3741] = { title = "Hilary's Necklace", description = "My friend Hilary lost her necklace, and we can't find it.  We've been fishing all day right here, and we looked around here already.  The only thing I can think of is that it fell into the lake.  Our parents don't want us to swim in the lake... my mom says there's some mean things underwater, but you look like you aren't scared of mean things.\n\nCould you find it for her, please?", objectives = "Find Hilary's Necklace, and return it to Hilary in Lakeshire.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "c043d48e62cfdb929e9ecab1779ff592404b4f58179f48592655b65b19a22055" }
quests[3903] = { title = "Milly Osworth", description = "You've shown yourself a dependable $c, $n.  Dependable, and not afraid to get your hands dirty, eh?\n\nI have a friend, Milly Osworth, who's in some trouble.  She's over with her wagon on the other side of the abbey, near the stable.  I'm sure she could use a pair of hands like yours.", objectives = "Speak with Milly Osworth.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "cc158908d018d41eb2b86a7097ddd56046d7c8bde599df356d72329389038b8b" }
quests[3904] = { title = "Milly's Harvest", description = "A gang of brigands, the Defias, moved into the Northshire Vineyards while I was harvesting!  I reported it to the Northshire guards and they assured me they'd take care of things, but... I'm afraid for my crop of grapes!  If the Defias don't steal them then I fear our guards will trample them when they chase away the thugs.\n\nPlease, you must help me!  I gathered most of my grapes into buckets, but I left them in the vineyards to the southeast.\n\nBring me those crates!  Save my harvest!", objectives = "Bring 8 crates of Milly's Harvest to Milly Osworth at Northshire Abbey.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "3cc87f7a12a81644556c72c65206fb825fa76e3461d392b421d8ca97dfb0508b" }
quests[4495] = { title = "A Good Friend", description = "A friend of mine named Iverron usually visits me at the same time every day. The strange thing is that he hasn't been by today at all -- he's several hours late, in fact.\n\nI admit, I am a little worried, $n. Iverron spends a lot of time over by the cave to the north, and I'm sure you know how dangerous it is there -- spiders, everywhere!\n\nIf you happen to be going that way, though, will you keep an eye out for him?", objectives = "Find Iverron by the cave to the north.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "3c878a124432e7fcd9dd10a6606c476a087b1594a84cc15ef642ad7dff9d7242" }
quests[5041] = { title = "Supplies for the Crossroads", description = "That attack on the caravan contained supplies we desperately needed.\n\nYou've been brave enough to take on the Razormane tribe so far, and I will ask you to do so again, but this time, I wonder if I could ask you to keep your eyes open for some of our lost supplies. You can probably find them throughout their camps, the quilboar getting fat off their dishonorable acts.\n\nThe people of the Crossroads would be in your debt.", objectives = "Find and return Crossroads' Supply Crates to Thork in the Barrens.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "bd3e24e72708e89eb7384e33d7abc48b714a1ba0a06bfd232e7d978c7d15da35" }
quests[5261] = { title = "Eagan Peltskinner", description = "Eagan Peltskinner is looking for someone to hunt wolves for him.  That's good news, because we're seeing a lot more wolves in Northshire Valley lately.\n\nIf you're interested then speak with Eagan.  He's around the side of the abbey, to the left.", objectives = "Speak with Eagan Peltskinner.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "d8c3474a21f39fb2b5416b001cbf7c2b11404108219a9e1ae143493f28ad8cee" }
quests[5541] = { title = "Ammo for Rumbleshot", description = "Hegnar Rumbleshot sells guns off the road to Anvilmar.  Riflemen and mortar teams spend a lot of time practicing out near his shop, and he's always needing fresh ammunition.\n\nBut... the last crate of ammo I sent him got lost along the way.  My courier said he was camped near the Grizzled Den when wendigo chased him away... and the fool left Rumbleshot's ammo behind!\n\n$n, can you get that ammo and take it to Rumbleshot?  He's been waiting on it and I'm sure he's running low.", objectives = "Bring Rumbleshot's Ammo to Hegnar Rumbleshot in Dun Morogh.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "9b60fdfe2ea55d7a8ab754f2b3c4a761253cfb86ae4bd5dd87558dd74ca66c6a" }
quests[5625] = { title = "Garments of the Light", description = "It's usually about this time that one of your power is tested to see if they're worthy of wearing robes denoting their place in the church. But to be honest, I got more pressing matters to look into. Citizen of Kharanos' just came in here and told me 'bout a hurt mountaineer just outside town to the south--name's Dolf.\n\nYou heal Dolf and give him Fortitude, and I'll consider you done with proving yourself. How's that sound?", objectives = "Find Mountaineer Dolf and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Maxan Anvol in Kharanos.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "7e6abf1dbe6a7154980b19a5944a5d040af24e9501c1193cbb3bb6325f1a13c0" }
quests[5626] = { title = "In Favor of the Light", description = "Hey! $n! Got a minute?!\n\nYa been following the Light now for long enough that you find your way to Maxan Anvol in Kharanos. He'll teach ya more about the path yer following, and if you prove worthy, give ya yer first set of robes to denote your station as a $gpriest:priestess;.\n\nNow get goin'! As soon as yer done here, head through the tunnel--he'll be waitin' for ya.", objectives = "Speak to Maxan Anvol in Dun Morogh.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "8b89faa2da996951d81977b2dd71cbb437ee273aa1e87baf8d85eaf4bd5ee68a" }
quests[5726] = { title = "Hidden Enemies", description = "One thing I will not tolerate are traitors in our midst, $n. But I would be a fool to play my hand so early--it would not sufficiently cut the corruption out of our lands and only cause the infection to grow worse.\n\nBut you, a young adventurer, could go places my agents could not... could learn the truth... could find the true head of the beast.\n\nIf you are brave enough, then enter Skull Rock to the east of Orgrimmar, find a lieutenant's insignia off one of the Burning Blade there, and return to me.", objectives = "Bring a Lieutenant's Insignia to Thrall in Orgrimmar.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "75b1f9a455a542fe311443a836aa80c39aae9076c46f610c26fc844406c59d55" }
quests[6068] = { title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Thotar at Razor Hill. He can put you on the path to earning a pet of your own.", objectives = "Speak with Thotar at Razor Hill.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "4754d81855242777eed79ba63a02b8c5f94c1aca843edf2b63f400ccfb02c999" }
quests[6384] = { title = "Ride to Orgrimmar", description = "For just a few coins I will have a wind rider bring you to Orgrimmar.  When you get there, you can take Zargh's Meats to Gryshka.  Her inn is in the Valley of Strength, not far from the Skytower, where my wind rider will drop you off.\n\nSpeak with me again when you are ready for the journey.", objectives = "Buy a wind rider to Orgrimmar from the wind rider master Devrak, then bring Zargh's Meats to Gryshka in Orgrimmar.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "be31abc616767d6104038c4fc6c0765a77042d8aacd027a19d5b9633978b29af" }
quests[6385] = { title = "Doras the Wind Rider Master", description = "I've written a letter of thanks to Zargh.  Will you deliver it for me?  If you've already been to the Crossroads and spoken with their wind rider master, then you can fly a wind rider back there.\n\nTake my letter to Doras, the wind rider master of Orgrimmar, and speak with him about transport to the Crossroads.", objectives = "Bring Gryshka's Letter to Doras in Orgrimmar.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "d1598046d796191fe2c95cda8b7fa3b2df0de8de1b4f381ba4ed3d9adfc81cca" }
quests[91741] = { title = "Nibbled-On Book", description = "<One of the kobolds dropped this book. It looks like the kobold might have tried to eat it.\r\n\r\nBrother Paxton inside the abbey has a small library he maintains. The book must have come from there.>", objectives = "Return the book to Brother Paxton.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "5de8ee9e778c45017dbef3399d2a6d67fff3638e232b3128489aa2e2dce3f057" }
quests[91743] = { title = "Rascally Rodents", description = "Those awful kobolds are eating my books! You have to get them back before they devour my whole library.", objectives = "Retrieve $1oa Stolen Books from kobolds in Northshire Valley and return them to Brother Paxton.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "4fdb9a354dc0369f29998d072093e28e4e6a9033e99219977db32f123bdf1eb4" }
quests[91745] = { title = "Mining Consultant", description = "Go talk to the new mining apprentice, Kelsey Fargo. She works right outside the mine and has probably seen what the kobolds are up to. Maybe she can teach you a thing or two about mining while you're at it.", objectives = "Talk to Kelsey Fargo outside the Echo Ridge Mine in Northshire Valley.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "a71aae06a95323338ba263130183f1ad3ae6af1c8e33adec9b01aa1f51ec71a8" }
quests[91752] = { title = "The Big Picture", description = "Every once in a while, a kobold comes through yelling \"Picture for Narf!\" I don't know who Narf is. Maybe one of the head kobolds at the back of the mine? I bet he has a whole sack of books by now.\r\n\r\nGo get those books and bring them to our local law enforcement, Marshal McBride. You should find a friend to help. Those kobolds inside the mine are a lot meaner.", objectives = "Retrieve a Sack of \"Picture\" Books from Shinyfinder Narf. Bring the sack to Marshal McBride just inside Northshire's Abbey.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "766c499777f0724c9008ecdfcbb6e10855ea7264641b8aed94238429677fe21f" }
quests[91758] = { title = "Follow That Kobold!", description = "You're not done with those kobolds yet. We just got word from Kelsey that a kobold left the mine carrying a large sack of books. I need you to track down this kobold so we can retrieve the books for Brother Paxton.\r\n\r\nGo talk to Tordrin Sternblade. He's the new Hunter trainer that just arrived from Ironforge. You can find him behind the abbey, near the stable. He can help you track this kobold thief.", objectives = "Speak to Tordrin Sternblade near the stable behind Northshire's Abbey.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "6eacc0e09dc6c4ebaead05c096c6443ec0b28d58bf5f27822fbb4f5a88aae73e" }
quests[92124] = { title = "Book Inventory", description = "We need to take stock of how many books are missing!\r\n\r\nGo talk to my useless assistant, Daniel. He can do a quick inventory and let us know how serious the problem is.\r\n\r\nHe's obsessed with the various trade professions in Elwynn Forest. The boy keeps focusing on those instead of his important work helping me.\r\n\r\nDon't let him prattle on about tradeskills, and find out what's happened to my books!", objectives = "Speak to Daniel, Brother Paxton's assistant in the library.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "a72cecede6984b8425b8023183dce1c1b6ad4c7a6eec96ef7b711199041c328a" }
quests[92742] = { title = "Testing the Wells", description = "We must determine the source and nature of the poison corrupting this land. Let us begin with the groundwater under the farms in the area.\r\n\r\nGo to the Jansen Stead in the north and the Molsen Farm northwest of here, and collect samples from the wells there.", objectives = "Use the Well Water Sample Kit to collect samples from the wells at the Jansen Stead and the Molsen Farm.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "aaf1b04df25e7ba35ac54646bc89b3d0c8e30cb2f1ede43f8342fe80b5eb10de" }
quests[92744] = { title = "Murloc Gills", description = "The corruption affecting Westfall's crops may have seeped into the ocean as well. If the local fish are affected too, it could doom Stormwind to famine.\r\nCollect gills from the murlocs along the shoreline and bring them to me. Murlocs are quite hardy, but their physiology is extremely sensitive to contaminants. Any toxins in the seawater will be readily apparent in the gills you find.", objectives = "Alba Fairmoon wants you to collect 7 Longshore Murloc Gills along the shoreline of Westfall.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "f08dfad059f91b98cdd6f0d376b5c482b91603ea75b6d698e9b8d998abc867ba" }
quests[92909] = { title = "Harvesting the Harvesters", description = "Oh no... I'm in for it now!\r\n\r\nI heard about the harvesters terrorizing the fields of Westfall, so I traveled all the way from Ironforge to see if I could recalibrate them. But they're far more aggressive than my calculations anticipated, and they chased me into this stable!\r\n\r\nIf I had some isosprings and gyrostabilizers from the harvesters, I could build a device to cover my escape. Could you gather the parts for me?", objectives = "Ozwin Ironsprocket at Saldean's Farm wants you to bring him 14 Golem Isosprings and 5 Harvester Gyrostabilizers.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "287ef758c77d180bd5d3d0491f48f6c7cae7deb78616ef3cef0567f1219467fd" }
quests[93963] = { title = "Exploring the Alliance", description = "Stormwind, Ironforge, and Darnassus all have unique peoples and cultures. As a guest of the Alliance here on Azeroth, you should take some time to visit each of our capital cities in turn. \r\n\r\nSpeak with Randal Emerson in the southern antechamber for directions to get you started.", objectives = "Speak with Randal Emerson in Stormwind Keep to receive further instructions. Use the instructions received to locate and speak with King Magni Bronzebeard, High Tinker Mekkatorque, and Tyrande Whisperwind.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "943d0817a55fe992a746bd39ee221589629a69852b288a7d28da540f91508692" }
quests[94373] = { title = "Call of Earth", description = "Aye, the time's come, young shaman. Ye've grown stout and sturdy, like the stone beneath our boots. Takin' up the shaman's path shows ye've got the wisdom o' the mountain, even before ye've proven yerself.. Ye've the grit of stone to walk the earth's path. \r\n\r\nBut to earn its favor, ye must face it proper. South o' here, the Frostmane trolls live in a cave.\r\n\r\nBring me two of their necklaces they wear--crafted from the Iceclaw bears. Then we'll speak more of yer future.", objectives = "Bring 2 Frostmane Bear Pendants to Teo Hammerstorm in Anvilmar.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "a38025dd1dec685327cf9ffccdb8a652b317ae8cfe3822694db59a0545dfb625" }
quests[94374] = { title = "Call of Earth", description = "Aye, sapta's a brew forged with magic, bindin' our spirit to the elements. Only a few shaman know the recipe, and it's nae for the weak-willed. Drink it, and ye will see what others can't. Hold true--it's only to be drunk in a sacred place.\r\n\r\nHead north to the Spirit Stone, tucked at the end of a hidden path up the mountain. Drink it there... see what the earth has to show ye.", objectives = "Find the Spirit Stone and drink the Earth Sapta.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "ab074bd82cafd6005aee0c49c1b80cd3835a72bbbce362bd4e9cde462be6847c" }
quests[94375] = { title = "Call of Earth", description = "Take this rough quartz from me and bring it to Teo Hammerstorm as proof o' our meeting. He will craft a totem for ye, and this pebble will be the heart o' it. As small as it may seem, ye will come to find that size does not matter, and that even the smallest o' things can outlast many others.\r\n\r\nBe patient, $n. Remain strong. And seek wisdom. This is what earth asks o' ye. In the end, ye shall become one with the earth--respect it as it shall respect ye.", objectives = "Bring the Rough Quartz to Teo Hammerstorm in Anvilmar.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "d432d217f9ab9563bd60af5b3962f27980f9ad17f775b7d6f207a08f4c5b9a80" }
quests[94472] = { title = "Earth Sapta", description = "", objectives = "Speak to Teo Hammerstorm for another Earth Sapta.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "7807a45aa089c83f811f31025ac9abedf49c459dfe28a4f3434431b83b47be52" }
quests[94914] = { title = "Moonglade", description = "All druids are welcomed to the sacred lands of Moonglade.  Keeper Remulos - Moonglade's guardian - keeps watch over all druids who hibernate there. I'll teach you the spell that lets you transport yourself there. Cast it whenever you seek Moonglade's knowledge or solace.\n\nAs for your first lesson here on Azeroth, travel to Moonglade and speak with Dendrite Starblaze in Nighthaven about the path you're now on. Good luck, young druid.", objectives = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "9731f3a36f86120eb1f40378c64316f04cb839358868d4739f71b10e69f5dd5e" }
quests[95036] = { title = "A Moon-Kissed Blade", description = "Trevan tells me that the worgen are a major threat to the citizens of Silverpine Forest. Despite their strength and resilience they can be killed, but there is one in particular that just doesn't ever seem to stay dead due to unknown magic.\r\n\r\nThat's the one that attacked us. He is known as Old Fire-Eye and he is the biggest and meanest of their kind. To put him down, we'll need a special kind of weapon.\r\n\r\nSpeak with Trevan and he will supply you with a list of what is needed to forge such a weapon.", objectives = "Speak with Trevan Rol in the Sepulcher and bring him the materials he requires.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "54aa7381d9f35b27e1cf321f29dc8fa4bce9aa7ee0776703976b3148680e804d" }
quests[96056] = { title = "Camping 101: Skinning", description = "Being able to skillfully harvest the skins and hides of fallen beasts is one of the more valuable skills an adventurer can possess.\r\n\r\nI reckon I know someone that can teach you how to craft a Camp Chair for your camp. Sometimes it's important to just take a load off, and you can use some of those hides you've gathered to make a comfy chair to sit in. A bit of relaxation can help ensure that you are at your peak condition and can strike where it counts the next time you find yourself in a dust-up.", objectives = "Speak with Balthus Stoneflayer in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "afc70e2bcbe0c884021783d5c48ecb2fd95e925a702d81881aaac7bf5ad4af88" }
quests[96102] = { title = "Camping 101: Tailoring", description = "Tailoring is a surprisingly potent tradeskill to invest in, and I'm sure it'll serve you well.\r\n\r\nI know someone that can teach you how to craft a Faction Banner for your camp, provided you have the skill for it. Inspiration and morale are a key part of success on any battlefield, and an inspirational banner can go a long way to keeping you energized.", objectives = "Speak with Snang in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "e04283bac8620a1cea8bb8929bbcba9e089bd8aec7b8d39ea1e5deee61710349" }
quests[96392] = { title = "Farsen's Watch", description = "Greetings to ye, friend. My name is Earthseer Farsen and I'm visiting Dun Morogh from Aerie Peak. As I was travelin', I couldn't help but notice that we have, well... a bit o' a Dark Iron Dwarf problem.\r\n\r\nIf ye have a moment, I can show ye what I mean. I've got a bit o' magic that should do the trick.", objectives = "Speak with Earthseer Farsen's and ask him to lend you his farsight to observe the Dark Iron threat.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "5d50682354d032b418c7e7d232a1fd4cb46ec786e512217f2e7fe9f2890898a2" }
quests[96608] = { title = "The Great Outdoors", description = "Greetings, $c. I can see you've got the look of an adventurer about you. This is good. The world needs more of us restless souls, seeking fortune and glory.\r\n\r\nYou'll need to learn to thrive in the wilds to be successful in this line of work. Not sure how your outdoor skills are but I can probably teach you a thing or two, if you'd be apt to learn.\r\n\r\nHave a seat near the fire and get comfortable. I'll walk you through it.", objectives = "Sit near Eric's Basic Campfire by typing /sit in the chat window and wait until you receive the Boosted Rest buff.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "6271f78ef7573147dd434121ab9ad36360756139e986d6bc5f7833e37d33559e" }
quests[96627] = { title = "The Adventurer", description = "$n, you have proven your competence as a protector thus far. That is why I am now entrusting you with an unusual task.\r\n\r\nI've heard of a new adventurer down the road by Goldshire. Go and see what he's doing.", objectives = "Speak to Sam Sarsparilla near Goldshire.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "919ce1e6e8e51a697f931a62b7b0424b8a6826d9fac7684557d61832555d04cb" }
quests[96628] = { title = "The Adventurer", description = "Wait, $n. I have another ask of you, before you brave that tunnel.\r\n\r\nMy mountaineers have reported an adventurer that's shown up just outside of Kharanos. Could you deliver these supplies to him?", objectives = "Deliver the Supply Bundle to Eric Brighthammer near Kharanos.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "ae9fcf11f90205a06c7ee6e3f2208f87be1e1beceb51ab292f45ffc2aee565d0" }
quests[96630] = { title = "The Adventurer", description = "<The journal appears to be quite plain, detailing the life and adventures of someone you've never heard of.\r\n\r\nThere are multiple entries mentioning camping. It seems to be quite... fun.>", objectives = "Bring the journal to Lyreena Duskblade near Dolanaar.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "abdc7c1171dfdae6ff9a4cacb9d5fcd4b0fecee5c702fc13a114a9b288bef175" }
quests[96638] = { title = "The Adventurer", description = "More and more adventurers like yourself have been seeking glory and fortune outside of the safety of Thendal Grove. There's one such adventurer who has made a camp outside of Shen'dar Village, along the road leading southwest out of Thendal Grove.\r\n\r\nSeek him out and see what you can learn from him that may help you in your own travels.", objectives = "Speak to Raan Wildwind near Shen'dar Village.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "de0e9c672b22788bc2a6620247c9e09094aa2b5205829daaa3787de8d2e8f414" }
quests[96652] = { title = "The Adventurer", description = "<The journal appears to be quite plain, detailing the life and adventures of someone you've never heard of.\r\n\r\nThere are multiple entries mentioning camping. It seems to be quite... fun.>", objectives = "Bring the journal to Brakk near Razor Hill.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "5ff96dfd572365689cf010f0fe1c5bab264ef256c95d6d7a2c66254a97585cab" }
quests[96656] = { title = "The Adventurer", description = "$n, you have proven yourself trustworthy in your endeavors against the Scarlet Crusade so far. That is why I am now entrusting you with an unusual task.\r\n\r\nI've heard of a new adventurer down the road by Brill. Go and see what she's doing.", objectives = "Speak to Eleanor Shackleton near Brill.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "187140875826d9d437799d867d305e486f724088b34d1ebc9ac7b57c90d76c9b" }
quests[96659] = { title = "The Adventurer", description = "Wait, $n. I have another ask of you, before you leave us.\r\n\r\nThere is an adventurer by the name of Kaga Wildhoof who has made camp just outside of Bloodhoof Village. She has greatly helped me in the past, and now I see my chance to repay her. Could you deliver these supplies to her?", objectives = "Deliver the Supply Bundle to Kaga Wildhoof near Bloodhoof Village.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "7dc20f635734ef1d3cf745b3b5dbb3f3b7db46b105de0b833245b716830140f0" }
quests[97249] = { title = "Favorite Food", description = "Now that I know his parents worry about how much he's actually filling that belly, I've got an idea. \r\n\r\nThey made me promise not to pack the same meal every day, so Migi grows a taste for more than one thing. Still, whenever the smoker's full and we're making sweetglazed hog belly sandwiches, he always shows up for lunch. We've started crumbling the leftover crispy glazed bits as a topping--something we can add daily. \r\n\r\nTake this to him. Maybe he'll start showing up early and bringing friends!", objectives = "Bring Migi's Lunch to him behind Grommash Hold", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "8d3f40918db7f93ba8657ee849b955e7714b51a6e74ddd4debdb5c2b503a900d" }
quests[97253] = { title = "Parts and Pieces", description = "Hey, got a sec?\r\n\r\nSo, apparently, nobody I've sent to deal with the recent pirate problem has come back alive. After five or six attempts I thought, \"what if I sent a machine instead?\" Turns out, scimitars double as screwdrivers in a pinch, and before I could redirect it home, it was already in pieces and scattered across their camp!\r\n\r\nI need those parts back, and since this is a quick little retrieval mission, I'd wager your odds for survival are MUCH higher than the others. Whaddya say?", objectives = "Collect $1oa Handfuls of Complicated Parts from the upper pirate camp south of Ratchet, then return to Wrenix the Wretched in Ratchet.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "df8d575e22704dc5f8e113dbbd7838f3a0134aa15cff03e778172c4f58e11560" }
quests[97277] = { title = "Grund and Gozwin", description = "Oi, had me back turned gettin' the boar roast ready when I heard me pal Gozwin screamin' fer his life!\r\n\r\nWicked fangs and a blur are all I saw when I turned. Such huge paws! A snow leopard was draggin' its gnomish catch away. I grabbed me shotgun and fired above the beast. It dropped him and sprinted off.\r\n\r\nLuckily, it hadn't done more than give ol' Goz some deep scratches.\r\n\r\nHead back to camp in the northwestern hills and retrieve Gozwin's Mechanic's Log. Kill that snow leopard too if you see it!", objectives = "Find Grund and Gozwin's camp in the hills to the northwest. Recover Gozwin's Mechanic's Log and kill the Snow Leopard Prowler.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "bcbbd9566196a59e70b5a54d1bb33e15deec0f2a719a841e38bba71a827dcc74" }
quests[97485] = { title = "Traditions of the Bluff", description = "Blessings of An'she, friend.\r\n\r\nWe tauren have a tradition of scattering incense to the winds and I was hoping you'd be interested in honoring this tradition.\r\n\r\nYou will need to craft the incense by purchasing herbs from Nida, cedar from Nata, sinew thread from Mahu in the mid rise, and ceremonial flint and tinder from Naal on the upper rise. Once you have these items, combine them and spread them off the south facing cliff of Hunter's Rise.\r\n\r\nYou will find a mat and incense at the ceremonial site.", objectives = "Purchase a Bundle of Herbs from Nida the herbalist, a Bundle of Ceder Twigs from Nata the enchanting supplier, and Sinew Thread from Mahu the leatherworking supplier and Ceremonial Flint and Tinder from Naal the cooking supplier.\r\n\r\nCombine the items and sprinkle the incense off of Hunter's Rise.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "309fe98adebd938fb09678b6e5ef48d59baf78f269910a69f1f15d45907f6c7b" }
quests[97894] = { title = "Business in Auberdine", description = "Pleasure to make yer acquaintance! Name's Borgus, of the one and only Steelhand family. You can always count on a Steelhand fer a fair deal!\r\n\r\nA few weeks back me brother Gorbold joined up with a merchant stall in Auberdine. Plenty of coin to be made supplyin' ships there, let me tell you! Lucky sod.\r\n\r\nI haven't heard from him since--mind checking on him if yer heading that way?\r\n\r\nThere's a new ship in the harbor that will take ye straight there. Head to the southern-most dock; can't miss it!", objectives = "Check on Gorbold Steelhand in Auberdine in Darkshore.\r\n\r\nBorgus mentioned a boat on the southern-most dock in Stormwind Harbor that can take you there.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "0ce22eb859ab7e87e15831dd2ca9c1d952a68b54d734b66f1eba8601953dc528" }
quests[97899] = { title = "Camping 101: Alchemy", description = "So, you chose to cook up brews and potions as an Alchemist. I'm sure that'll come in handy in your travels.\r\n\r\nI reckon I know someone that can teach you how to craft a Mana Well for your camp. Build one of these and all of the healers and spellcaster types will come running to get a refreshing taste.", objectives = "Speak with Whuut in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "bfd39efa1caa5bda8aa10307dddfec4fd720304872faa8ac5110e75c16980376" }
quests[97901] = { title = "Camping 101: Enchanting", description = "Enchanters make everything better and are always welcome at any camp out in the wilds.\r\n\r\nI reckon I know someone that can teach you how to craft an Enchanted Lute for your camp. It's so important to find entertainment during your downtime, and this bit of magic can help ensure you are ready to weather all sorts of challenges when you hit the old dusty trail once again.", objectives = "Speak with Jhag in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "b686c0455f69c5c5e0cf5ad008300282862468f1b83dc055c1a6c0fa4e18a46b" }
quests[97905] = { title = "Camping 101: Herbalism", description = "Looks to me like you've gained some skill in herbalism. Picking flowers isn't just for dilly-dallying, you know. It can be useful... and profitable.\r\n\r\nI reckon I know someone that can teach you how to craft an Incense Candle for your camp. High spirits are a key component to keeping healers and spellcasters in the fight, and an Incense Candle can provide a boost that magic users will surely appreciate.", objectives = "Speak with Jandi in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "0ee480a41d25991c098ea7439c9e6a91ee0c1f16c82bb6ca3d5175a089d60c73" }
quests[97906] = { title = "Camping 101: Leatherworking", description = "You've become a leatherworker. Good for you, $c. I reckon I know someone that can teach you how to make yourself a tent that will keep you cool on hot days, and dry on rainy days.\r\n\r\nWith a good tent over your head, you'll ensure that you get all the rest you need to stay sharp on your travels.", objectives = "Speak with Karolek in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "8d50100f46db7e86340abc56c8a466beefa7178fa41fc9cf531b0c2a1c52b37e" }
quests[97908] = { title = "Camping 101: Skinning", description = "Being able to skillfully harvest the skins and hides of fallen beasts is one of the more valuable skills an adventurer can possess.\r\n\r\nI reckon I know someone that can teach you how to craft a Camp Chair for your camp. Sometimes it's important to just take a load off, and you can use some of those hides you've gathered to make a comfy chair to sit in. A bit of relaxation can help ensure that you are at your peak condition and can strike where it counts the next time you find yourself in a dust-up.", objectives = "Speak with Thuwd in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "20b79cedb629c9f4f66fb7fb57667d8254f940b57014dc0a57365f03443ea539" }
quests[97924] = { title = "Camping 101: Skinning", description = "Being able to skillfully harvest the skins and hides of fallen beasts is one of the more valuable skills an adventurer can possess.\r\n\r\nI reckon I know someone that can teach you how to craft a Camp Chair for your camp. Sometimes it's important to just take a load off, and you can use some of those hides you've gathered to make a comfy chair to sit in. A bit of relaxation can help ensure that you are at your peak condition and can strike where it counts the next time you find yourself in a dust-up.", objectives = "Speak with Helene Peltskinner in Goldshire to learn to craft a camping item for your profession once you have shown proficiency in your skill.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "96cc8c0633f076472ad4a8e00c98fe7ee39a0fc97ad952b32c8a25399ce63f1c" }
quests[97977] = { title = "Nature's Call", description = "The Gnarlpine furbolg would not turn on their ancient allies so readily. We must learn more of their plight.\r\n\r\nSearch their abandoned homes for totems. If any survived the chaos of their departure, their engravings may tell us more of what happened here.\r\n\r\nYou'll find their camps along the western edge of the glen, though the grell and grellkin may have scattered them beyond.", objectives = "Collect $1oa  Gnarlpine Totems and bring them to Tarindrella.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "b65c31834352260190ea15ddd6845c71caa745e4ec61d2061c6bf1ec5d8ec3cf" }
quests[97979] = { title = "The Goddess Provides", description = "You are born kaldorei--the children of the stars--and have inherited a birthright unlike any other in this world. Elune's grace may illuminate our strengths, helping our strikes hit true, or it may help conceal us just as the moon may eclipse the sun.\r\n\r\nOur Long Vigil after the defense of Mount Hyjal has ended, and we have joined an Alliance of others--which you will meet in due time. For now, you are nestled in the boughs of Teldrassil.\r\n\r\nDemonstrate Mother Moon's gifts, and bask in her blessings.", objectives = "Cast Elune's Light and Shadowmeld.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "657f3cac83edf719981c7e0af68b0e56157d0ae284e154c3d02578f9e3cf4501" }
quests[98319] = { title = "Secure the Mountain", description = "It's bad enough havin' a troll problem, but the mountains are filled tae the brim with wendigos! They normally keep to their own caves, but they seem tae be spreadin' like bunnies. Now they've filled the Grizzled Den north of here.\r\n\r\nIf we want Whitebeard's report, we're gonna need to find my partner Cornelius. The blockhead got a little too excited and charged in head first. Brave, but stupid.\r\n\r\nHead into the cave and see where he is. And feel free to take out some the beasts while yer at it.", objectives = "Find Mountaineer Cornelius in the Grizzled Den for Mountaineer Gretchen.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "d11335a8bc3b30f1b8b141b4e14d5be546a96894014a9a9e25a3a99808573277" }
quests[98321] = { title = "Flintfire's Shipment", description = "Hoha! Good to see a $r who's not afraid to get their hands dirty.\r\n\r\nIf yer lookin' fer work, I'm afraid I'm a little short on supplies at the moment. Our most reliable source of ore has been overrun by wendigo and now the cave has been abandoned. The miners had to drop everything when they fled!\r\n\r\nSay, why don't ye poke yer head around the Grizzled Den to the west and see if you can find some of our missing shipments. It would save us a great deal o' trouble.", objectives = "Collect $1oa Flintfire Shipments from the Grizzled Den for Tongus Flintfire in Kharanos.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "2f87bfa7062b253dbb3fc4a2df19b5e00a360445352c1ace534393b022d42b72" }
quests[98322] = { title = "Secure the Mountain", description = "Spelunking dark caves is adventurer business. My job's just to make reports and send them over to Ironforge.\r\n\r\nTrouble is, one of my reports hasn't... well, reported back. I asked a few mountaineers to learn more about the wendigo problem we have out here, but I haven't heard from them.\r\n\r\nIf you're already going to be out and about, what say you don't check in with Mountaineer Gretchen just west of town. I'm late enough as it is!", objectives = "Check in on Mountaineer Gretchen west of Kharanos.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "f090aa21f62b0f24fc980ea6c4901b3fc566fdb4bf5d5e37752e95aa05d546fe" }
quests[98326] = { title = "Frosthowl", description = "Do ye know how hard it is to fish on a frozen lake? My poor husband, Paxton, has been out in the middle of it for days and we barely have a single sack to show fer it.\r\n\r\nWell, we DID have a sack to show fer it. Until the thrice-damned wendigo attacked me and made off with our haul. It'll take us weeks to fish all that back up! If that loudmouth Frosthowl didn't scare 'em all off, anyway.\r\n\r\nDo us a favor and get it back, aye? Drooling brute is hiding somewhere deep in the Grizzled Den to the southeast.", objectives = "Slay Frosthowl and collect the Sack of Fish for Gretta Ganter in Brewnall Village", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "bc8687979a5c3447aed59372468fd68bf250f65a710b5cb5284298d32dc72690" }
quests[98407] = { title = "Show of Force", description = "If the gnolls are growing so bold they are willing to camp this close to humans, there's no telling how much further they'll go. We need to deter them.\r\n\r\nThe beasts are hardly organized, but they seem to respect strength above all else. If we can slay the worst of them, maybe claim some of their trophies, we can remind these gnolls why they should stay in the hills where they belong.\r\n\r\nShould you see any of their thrashers, bring me their collars. That should put the fear of the Alliance back into them.", objectives = "Collect $1oa Spiked Collars from Gnoll Thrashers for Deputy Feldon near Lakeshire.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "4e150919e1ec190e5adbb432758c3da6fb835035dcdb33ea59cb1df8f98faf29" }
quests[98574] = { title = "Hallowed Memorandum", description = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the priest trainer Branstock. Take a gander at it and go find him inside Anvilmar when you've a chance.", objectives = "Read the Hallowed Memorandum and speak to Branstock Khalder in Anvilmar.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "a322f6d9832e397f8b4d969c1b767226854cd2d59f83cb7fc61f638720a46309" }
quests[98581] = { title = "Archaic Rune", description = "While you were helping me out, this rune was given to me to pass on to you. Take some time to read it when you have a chance. Based on the Wildhammer style to these inscriptions, I'm guessin' this came from the shaman trainer Teo Hammerstorm. Take a gander at it and go find him inside Anvilmar when you've a chance.", objectives = "Read the Archaic Rune and speak to Teo Hammerstorm in Anvilmar.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "2ddd86545294e2b643b2bf0f58cffe667d9893d5cc00ab32cb41fadd59c0d5b4" }
quests[99051] = { title = "Threat from Below", description = "It wouldn't be the first time those snakes bothered us. They need to be taught that their presence is not tolerated here.\r\n\r\nFind where their scouts are setting up camp and slaughter them. Bring me back their fins as proof. We need to act fast to make sure they understand.", objectives = "Collect $1oa Naga Spinefins.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "9060bfbbb34ca6bff28ac511fb3a06908ec654db47aca837f48bb43b4434077b" }
quests[99158] = { title = "Dawn in the Mountains", description = "There's a priest out in the mountains that belongs to an organization called the Argent Dawn. They're a holy group that is dedicated to finding and destroying the unholy and unnatural.\r\n\r\nFather Gavin though, he's mostly the type that seeks to help and heal everyone rather than grab a weapon. He's fixed up an old building to serve as a rest spot for travelers and called it Misty Pine Refuge. I've got a shipment of holy candles that I need to get him. Could you bring them to him if your going that way?", objectives = "Bring the crate of candles to Father Gavin at Misty Pine Refuge.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "ff6aed7957ccfefad2694cded07ace2f67ec1bc694e9d3a6db7ee8ed904fdc99" }
quests[99159] = { title = "Finding Warmth", description = "My hearth is open to warm any soul, but I'd like to ask you to help me if you could.\r\n\r\nI simply need more firewood. It is something I would normally do myself, but I have been preoccupied by other tasks.", objectives = "Collect $1oa pieces of firewood.", source = "native Forever enUS questcache.wdb build 70124", flavor = "forever", originFlavor = "forever", locale = "enUS", sourceBuild = 70124, sourceHash = "e352f270d0fc23bf336e8cfb236a024572347300f98dd96e0e4063d7f3a2e0e5" }
